<?php

namespace Database\Seeders;

// NOTICE: The records generated by this seeder are fictional sample data
// intended for testing and demonstration purposes only.
// These records do not represent actual faculty members or panelists.

use App\Models\Faculty;
use App\Models\Panel;
use App\Models\Research;
use Illuminate\Database\Seeder;
use RuntimeException;

class PanelSeeder extends Seeder
{
    private const RESEARCH_LIMIT = 10;

    public function run(): void
    {
        $researches = Research::query()
            ->inRandomOrder()
            ->limit(self::RESEARCH_LIMIT)
            ->get();
        $facultyCount = Faculty::query()->count();

        if ($researches->isEmpty()) {
            throw new RuntimeException('PanelSeeder requires at least one existing research record.');
        }

        if ($facultyCount === 0) {
            throw new RuntimeException('PanelSeeder requires at least one existing faculty record.');
        }

        $created = 0;

        foreach ($researches as $research) {
            $assignments = min(random_int(1, 3), $facultyCount);
            $facultyIds = Faculty::query()
                ->inRandomOrder()
                ->limit($assignments)
                ->pluck('id');

            foreach ($facultyIds as $facultyId) {
                $panel = Panel::factory()->make([
                    'research_id' => $research->id,
                    'faculty_id' => $facultyId,
                ]);

                $assignment = Panel::query()->firstOrCreate([
                    'research_id' => $panel->research_id,
                    'faculty_id' => $panel->faculty_id,
                ]);

                if ($assignment->wasRecentlyCreated) {
                    $created++;
                }
            }
        }

        $this->command?->info("Created {$created} sample panelist assignments.");
    }
}